'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const zlib = require('node:zlib');
const CONFIG = JSON.parse(zlib.gunzipSync(Buffer.from('', 'base64')).toString('utf8'));
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
const normalized = b => Buffer.from(b.toString('utf8').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n'), 'utf8');
function fail(message) { throw new Error(message); }
function writeJson(file, value) { fs.writeFileSync(file, JSON.stringify(value, null, 2), 'utf8'); }
function inside(root, file) {
    const rel = path.relative(root, file);
    return rel !== '..' && !rel.startsWith('..' + path.sep) && !path.isAbsolute(rel);
}
function sourcePath(root, relative) {
    if (!relative.startsWith('src/')) fail('Only src files are allowed: ' + relative);
    const target = path.resolve(root, ...relative.split('/'));
    if (!inside(root, target)) fail('Unsafe target path: ' + relative);
    if (!fs.existsSync(target) || !fs.statSync(target).isFile()) fail('Required source file is missing: ' + relative);
    if (!inside(root, fs.realpathSync(target))) fail('Source file points outside the project: ' + relative);
    return target;
}
function snapshot(root) {
    const result = {};
    function walk(dir) {
        for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
            const file = path.join(dir, entry.name);
            if (entry.isSymbolicLink()) continue;
            if (entry.isDirectory()) walk(file);
            else if (entry.isFile()) result[path.relative(root, file).split(path.sep).join('/')] = sha(fs.readFileSync(file));
        }
    }
    walk(path.join(root, 'src'));
    return result;
}
function checkSnapshot(root, expected, changes = new Map()) {
    const actual = snapshot(root);
    for (const [rel, hash] of Object.entries(expected)) {
        const wanted = changes.has(rel) ? changes.get(rel) : hash;
        if (actual[rel] !== wanted) fail('Source changed unexpectedly: ' + rel);
    }
    for (const rel of Object.keys(actual)) if (!(rel in expected)) fail('An additional source file appeared during installation: ' + rel);
}
function atomicWrite(file, bytes) {
    const temp = file + '.tamar-' + crypto.randomUUID() + '.tmp';
    try {
        fs.writeFileSync(temp, bytes, { flag: 'wx' });
        fs.renameSync(temp, file);
    } finally {
        if (fs.existsSync(temp)) fs.unlinkSync(temp);
    }
}
function loadState(work) {
    const normal = path.join(work, 'state.json');
    const backup = path.join(work, 'transaction.json');
    const file = fs.existsSync(normal) ? normal : backup;
    if (!fs.existsSync(file)) return null;
    const state = JSON.parse(fs.readFileSync(file, 'utf8'));
    if (state.version !== CONFIG.version) fail('Unsupported transaction version.');
    return state;
}
function saveState(work, state) {
    writeJson(path.join(work, 'state.json'), state);
    if (state.backupRoot) writeJson(path.join(state.backupRoot, 'transaction.json'), state);
}
function prepare(rootArgument, work) {
    const root = fs.realpathSync(path.resolve(rootArgument));
    const pkg = path.join(root, 'package.json');
    if (!fs.existsSync(pkg)) fail('package.json not found; choose the Tamar project root.');
    const packageJson = JSON.parse(fs.readFileSync(pkg, 'utf8').replace(/^\uFEFF/, ''));
    if (typeof packageJson.scripts?.build !== 'string') fail('The project has no npm build script.');
    const sidebarFile = sourcePath(root, 'src/components/layout/Sidebar.jsx');
    const sidebarSource = fs.readFileSync(sidebarFile, 'utf8');
    if (!sidebarSource.includes('tamar-sidebar-icon-group-v4am1') || !sidebarSource.includes('tamar-sidebar-count-v4am1') || !sidebarSource.includes('{badge}')) {
        fail('The Wave 4AM.1 live sidebar badge is missing. No source was changed.');
    }
    if (sidebarSource.includes('name="bell"') || sidebarSource.includes('tamar-v22-sidebar-notification')) {
        fail('The sidebar does not match the expected no-bell layout. No source was changed.');
    }
    const pending = [];
    for (const file of CONFIG.files) {
        const target = sourcePath(root, file.path);
        const before = fs.readFileSync(target);
        const n = sha(normalized(before));
        if (n === file.afterNormalized) continue;
        if (n !== file.beforeNormalized) {
            fail('Source mismatch: ' + file.path + '\nExpected source after Wave 4AM.1, or Wave 4AN already installed. No source has been written.');
        }
        pending.push({ path: file.path, beforeHash: sha(before), afterHash: sha(Buffer.from(file.afterBase64, 'base64')) });
    }
    const state = { version: CONFIG.version, root, changes: pending, snapshot: snapshot(root), needsApply: pending.length > 0, backupRoot: null, status: 'PREPARED' };
    saveState(work, state);
    console.log('Source preflight: PASS (' + CONFIG.files.length + ' target files; ' + pending.length + ' need updating)');
    console.log('Protected source snapshot: ' + Object.keys(state.snapshot).length + ' files');
}
function apply(work) {
    const state = loadState(work);
    if (!state || state.status !== 'PREPARED') fail('No prepared installation plan.');
    if (!state.needsApply) { console.log('Already installed; source was not changed.'); return; }
    checkSnapshot(state.root, state.snapshot);
    const backupParent = path.join(state.root, '.tamar-backups');
    fs.mkdirSync(backupParent, { recursive: true });
    if (!inside(state.root, fs.realpathSync(backupParent))) fail('The backup directory points outside the project.');
    const date = new Date();
    const two = n => String(n).padStart(2, '0');
    const stamp = date.getFullYear() + '-' + two(date.getMonth()+1) + '-' + two(date.getDate()) + '_' + two(date.getHours()) + '-' + two(date.getMinutes()) + '-' + two(date.getSeconds());
    state.backupRoot = path.join(backupParent, 'dashboard-wave4an1-' + stamp + '-' + crypto.randomUUID().slice(0, 8));
    fs.mkdirSync(state.backupRoot);
    // Create and validate every backup before the first project source write.
    for (const change of state.changes) {
        const original = fs.readFileSync(sourcePath(state.root, change.path));
        if (sha(original) !== change.beforeHash) fail('Source changed before backup: ' + change.path);
        const backupFile = path.join(state.backupRoot, ...change.path.split('/'));
        fs.mkdirSync(path.dirname(backupFile), { recursive: true });
        fs.writeFileSync(backupFile, original, { flag: 'wx' });
        if (sha(fs.readFileSync(backupFile)) !== change.beforeHash) fail('Backup verification failed: ' + change.path);
    }
    fs.copyFileSync(__filename, path.join(state.backupRoot, 'restore-runner.cjs'));
    fs.writeFileSync(path.join(state.backupRoot, 'Restore.ps1'), [
        '$ErrorActionPreference = "Stop"',
        '$node = Get-Command node.exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1',
        'if (-not $node) { $node = Get-Command node -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1 }',
        'if (-not $node) { throw "Node.js was not found." }',
        '& $node.Source (Join-Path $PSScriptRoot "restore-runner.cjs") rollback $PSScriptRoot',
        'if ($LASTEXITCODE -ne 0) { throw "Restore stopped; see the conflict details above." }'
    ].join('\r\n') + '\r\n', 'utf8');
    state.status = 'APPLYING';
    saveState(work, state);
    console.log('Backup: ' + state.backupRoot);
    for (const change of state.changes) {
        const target = sourcePath(state.root, change.path);
        if (sha(fs.readFileSync(target)) !== change.beforeHash) fail('Source changed before writing: ' + change.path);
        const payload = CONFIG.files.find(file => file.path === change.path);
        atomicWrite(target, Buffer.from(payload.afterBase64, 'base64'));
        if (sha(fs.readFileSync(target)) !== change.afterHash) fail('Written source verification failed: ' + change.path);
        console.log('Updated: ' + change.path);
    }
    state.status = 'APPLIED';
    saveState(work, state);
}
function verify(work, final) {
    const state = loadState(work);
    if (!state || !['APPLIED', 'VERIFIED', 'COMPLETED'].includes(state.status)) fail('No applied transaction to verify.');
    const changes = new Map(state.changes.map(change => [change.path, change.afterHash]));
    checkSnapshot(state.root, state.snapshot, changes);
    for (const file of CONFIG.files) {
        const source = fs.readFileSync(sourcePath(state.root, file.path));
        if (sha(normalized(source)) !== file.afterNormalized) fail('Installed payload mismatch: ' + file.path);
    }
    const sidebar = fs.readFileSync(path.join(state.root, 'src/components/layout/Sidebar.jsx'), 'utf8');
    if (sidebar.includes('name="bell"') || sidebar.includes('tamar-v22-sidebar-notification')) fail('The obsolete sidebar bell is still present.');
    if (!sidebar.includes('tamar-sidebar-icon-group-v4am1') || !sidebar.includes('{badge}')) fail('The original live counter was not preserved.');
    state.status = final ? 'COMPLETED' : 'VERIFIED';
    saveState(work, state);
    console.log('Installed payload hashes: PASS');
    console.log('Unchanged source files: PASS');
    console.log('Original live sidebar counter retained; Sidebar.jsx not edited: PASS');
    if (final) console.log('Backup retained: ' + state.backupRoot);
}
function rollback(work) {
    const state = loadState(work);
    if (!state || !state.backupRoot) { console.log('No project source writes to restore.'); return; }
    const conflicts = [];
    let restored = 0;
    for (const change of state.changes) {
        const file = path.resolve(state.root, ...change.path.split('/'));
        const backup = path.join(state.backupRoot, ...change.path.split('/'));
        if (!inside(state.root, file) || !fs.existsSync(file) || !inside(state.root, fs.realpathSync(file))) { conflicts.push(change.path); continue; }
        const current = sha(fs.readFileSync(file));
        if (current === change.beforeHash) continue;
        if (current !== change.afterHash) { conflicts.push(change.path); continue; }
        if (!fs.existsSync(backup) || sha(fs.readFileSync(backup)) !== change.beforeHash) { conflicts.push(change.path); continue; }
        atomicWrite(file, fs.readFileSync(backup));
        restored++;
    }
    state.status = conflicts.length ? 'ROLLBACK_CONFLICT' : 'ROLLED_BACK';
    saveState(work, state);
    console.log('Restored source files: ' + restored);
    console.log('Backup retained: ' + state.backupRoot);
    if (conflicts.length) fail('These files changed after installation and were NOT overwritten:\n' + conflicts.join('\n'));
    console.log('Source rollback completed. Build output in dist is not restored; rebuild before using a production preview.');
}
try {
    const [command, a, b] = process.argv.slice(2);
    if (command === 'prepare') prepare(a, b);
    else if (command === 'apply') apply(a);
    else if (command === 'verify') verify(a, false);
    else if (command === 'finalize') verify(a, true);
    else if (command === 'rollback') rollback(a);
    else fail('Unknown command.');
} catch (error) { console.error(error.message); process.exitCode = 1; }
